import json, subprocess, sys, copy

MAIN = '/app/submission/main.py'

def run(doc, raw=None):
    if raw is None:
        raw = json.dumps(doc).encode()
    p = subprocess.run([sys.executable, '-I', '-B', MAIN], input=raw, capture_output=True, timeout=45)
    return p

def basic_doc():
    return {
        "version": 1,
        "config": {
            "accounts": [
                {"id": "alice", "default": "sip:alice@lab.test",
                 "aliases": ["sip:alice@lab.test", "sip:desk@lab.test", "tel:+12025550100"]},
                {"id": "bob", "default": "sip:bob@lab.test",
                 "aliases": ["sip:bob@lab.test"]}
            ],
            "peers": [
                {"id": "edge", "mode": "access", "accounts": []},
                {"id": "relay1", "mode": "relay", "accounts": ["alice"]}
            ],
            "ttl_ms": 100,
            "capacity": 4
        },
        "events": []
    }

def hdr(headers):
    out = []
    for k, v in headers:
        if isinstance(v, list):
            for item in v:
                out.append(k + ': ' + item)
        else:
            out.append(k + ': ' + v)
    return out

def wire(method='MESSAGE', target='sip:bob@lab.test', headers=None, body=b'', raw=None):
    if raw is not None:
        return raw
    lines = [method + ' ' + target + ' SIP/2.0']
    if headers:
        lines.extend(hdr(headers))
    lines.append('Content-Length: ' + str(len(body)))
    text = '\r\n'.join(lines) + '\r\n\r\n'
    return text.encode('latin-1') + body

def ev(t=0, peer='edge', auth='alice', egress='external', w=None):
    if w is None:
        w = wire()
    return {"t": t, "peer": peer, "auth": auth, "egress": egress, "wire_hex": w.hex()}

def base_headers(**kw):
    h = [("From", "<sip:alice@lab.test>;tag=t"),
         ("To", "<sip:bob@lab.test>"),
         ("Call-ID", "c1"),
         ("CSeq", "1 MESSAGE")]
    h.extend(kw.get('extra', []))
    return h

FAILS = []
def check(name, got, want):
    if got != want:
        FAILS.append((name, got, want))
        print('FAIL', name, '\n  got :', got, '\n  want:', want)
    else:
        print('ok  ', name)

def decisions(doc):
    p = run(doc)
    if p.returncode != 0:
        return ('EXIT', p.returncode, p.stderr.decode()[:200])
    return json.loads(p.stdout)

def one(name, event, want_result=None, want_counts=None, doc=None):
    d = doc or basic_doc()
    d['events'] = [event]
    out = decisions(d)
    if out == ('EXIT', 2, ''):
        FAILS.append((name, out, 'valid envelope'))
        print('FAIL', name, '-> exit 2')
        return
    if want_result is not None:
        check(name + '/result', out['results'][0], want_result)
    if want_counts is not None:
        check(name + '/counts', (out['accepted'], out['replayed'], out['rejected'], out['live']), want_counts)

def rej(name, event, reason, doc=None):
    one(name, event, {'index':0,'decision':'reject','reason':reason}, (0,0,1,0), doc)
